/* answer bank: system design concepts and 'how do I design X' outlines. Generated from a source outline; edit freely. */
(function () {
  var OR = (window.OR = window.OR || {}); OR.qa = OR.qa || [];
  OR.qa.push(
    {"id": "sd-cap-theorem", "title": "CAP theorem, and what it really says", "q": ["what is the cap theorem", "cap theorem explained", "consistency availability partition tolerance", "can you have all three of cap", "cp vs ap system", "explain cap in an interview"], "tags": "cap theorem consistency availability partition tolerance cp ap linearizable brewer", "see": ["#/system-design/fundamentals/cap-pacelc", "#/system-design/fundamentals/consistency-models"], "a": "CAP says that **when a network partition happens, a distributed store must choose between consistency (every read sees the latest write) and availability (every non-failed node answers)**. Partitions can't be ruled out, so \"pick two of three\" is misleading: the real choice is CP or AP, and it only bites during a partition.", "more": "- **CP**: refuse or block some requests during a partition to avoid stale or conflicting data (e.g. majority-quorum stores).\n- **AP**: keep answering from local state, reconcile later (Dynamo-style stores).\n- \"Consistency\" here means linearizability, not the C in ACID.\n- Decide per feature: balances and unique usernames lean CP, likes and feeds lean AP.\n- Without a partition the everyday trade is latency vs consistency (see PACELC)."},
    {"id": "sd-pacelc", "title": "PACELC theorem", "q": ["what is pacelc", "pacelc vs cap", "latency vs consistency trade off in distributed systems", "what happens in cap when there is no partition", "explain pacelc"], "tags": "pacelc cap latency consistency else partition tradeoff replicas", "see": ["#/system-design/fundamentals/cap-pacelc"], "a": "PACELC extends CAP: **if there is a Partition, choose Availability or Consistency; Else (normal operation), choose Latency or Consistency.** Even with a healthy network, keeping replicas in sync costs round trips, so you either wait for agreement (consistent, slower) or answer from the nearest replica (fast, maybe stale).", "more": "- PA/EL: Dynamo-style stores at default settings (available, low latency, eventually consistent).\n- PC/EC: single-leader SQL with synchronous replication, Spanner-style systems.\n- It describes the common case, while CAP only describes the rare partition case.\n- In an interview say which side each feature picks and why."},
    {"id": "sd-consistency-models", "title": "Strong, eventual, causal and read-your-writes consistency", "q": ["what are consistency models", "strong vs eventual consistency", "what is causal consistency", "what is read your writes consistency", "linearizability explained", "monotonic reads", "eventual consistency meaning"], "tags": "consistency strong eventual causal linearizable read your writes monotonic reads session sequential", "see": ["#/system-design/fundamentals/consistency-models"], "a": "A consistency model is a promise about what reads can see after writes. From strongest to weakest: **linearizable** (behaves like one copy, real-time order), **causal** (cause always seen before effect), **session guarantees** (read-your-writes, monotonic reads), **eventual** (replicas converge if writes stop). Stronger costs latency and availability, so use the weakest one the feature tolerates.", "more": "- Read-your-writes: you always see your own updates. Fix with leader reads or a write timestamp.\n- Monotonic reads: you never see time go backwards between two reads.\n- Eventual is not \"no rules\": concurrent writes still need last-write-wins, a merge function, or CRDTs.\n- Balance or unique username: linearizable. Like count: eventual. Comment replies: causal."},
    {"id": "sd-read-your-writes", "title": "Fix \"I saved but I see old data\" with async replicas", "q": ["how to provide read your writes with replicas", "user updates profile then sees old value", "replica lag stale read after write", "read after write consistency", "how to avoid stale reads from followers"], "tags": "read your writes replication lag stale follower session leader read timestamp sticky", "see": ["#/system-design/fundamentals/consistency-models", "#/system-design/fundamentals/replication-sharding"], "a": "After a user writes, **read their data from the leader (or a replica known to be caught up) for a short window**, or send the write's log position/timestamp with later reads and only use replicas that have reached it. Other users can still read replicas.", "more": "- Simple version: route the user's reads to the leader for a few seconds after any write (a bit above typical lag).\n- Better: return a version token with the write; the router skips replicas behind it.\n- Sticky routing to one replica gives monotonic reads but not read-your-writes by itself.\n- Cross-device reads need the token stored server-side, not just on one device."},
    {"id": "sd-acid-vs-base", "title": "ACID vs BASE", "q": ["acid vs base", "what does acid stand for", "what is base in databases", "explain acid properties", "atomicity consistency isolation durability", "base eventually consistent meaning"], "tags": "acid base atomicity consistency isolation durability basically available soft state eventual transactions", "see": ["#/system-design/fundamentals/databases"], "a": "**ACID** (atomicity, consistency, isolation, durability) describes transactional databases: a transaction is all-or-nothing, keeps invariants, doesn't see others' half-done work, and survives crashes. **BASE** (basically available, soft state, eventually consistent) is a looser style for scale: stay up and let replicas converge later. Use ACID for money and inventory, BASE for feeds and counters.", "more": "- Atomicity: all writes of a transaction apply or none do.\n- Consistency (ACID): the transaction moves the DB between valid states (constraints hold). Different from CAP's C.\n- Isolation: concurrent transactions behave as if serial, to a chosen level.\n- Durability: committed data survives a crash (write-ahead log).\n- BASE is a tradeoff label, not a formal guarantee."},
    {"id": "sd-replication-types", "title": "Leader-follower, multi-leader and leaderless replication", "q": ["what is database replication", "leader follower replication", "multi leader vs single leader", "leaderless replication", "how does replication work", "sync vs async replication"], "tags": "replication leader follower primary replica multi leader leaderless dynamo synchronous asynchronous", "see": ["#/system-design/fundamentals/replication-sharding"], "a": "**Leader-follower**: all writes go to one leader, which streams its log to followers that serve reads. **Multi-leader**: several leaders accept writes (e.g. one per region) and sync with each other, which needs conflict resolution. **Leaderless**: any replica accepts writes; clients write to W and read from R replicas (quorum), with read repair fixing stale ones.", "more": "- Async replication: fast writes, but a leader crash can lose the latest writes and followers lag.\n- Sync replication: no loss, but a slow follower stalls writes (usually one sync follower, rest async).\n- Leader-follower is the default; scale reads with followers, writes need sharding.\n- Multi-leader/leaderless trade simplicity for availability and write locality.\n- Failover: detect leader death, promote the most caught-up follower, avoid split brain."},
    {"id": "sd-quorum", "title": "Quorum reads and writes (R + W > N)", "q": ["what is a quorum", "r + w > n explained", "quorum reads and writes", "n r w dynamo quorum", "how many replicas to read and write", "tunable consistency"], "tags": "quorum n r w dynamo cassandra replicas overlap majority tunable consistency", "see": ["#/system-design/fundamentals/consistency-models", "#/system-design/distributed-kv-store"], "a": "With N replicas, a write must be acknowledged by W and a read must query R. **If R + W > N, every read set overlaps the latest write set**, so a read sees at least one up-to-date copy and picks the newest version. Example: N=3, W=2, R=2 tolerates one failed replica for both reads and writes.", "code": {"py": "def overlaps(n, r, w):\n    return r + w > n\n\nprint(overlaps(3, 2, 2))   # True: majority read + majority write\nprint(overlaps(3, 1, 1))   # False: a read can miss the write"}, "more": "- W=N, R=1: fast reads, writes fail if any replica is down.\n- W=1, R=N: fast writes, slow reads.\n- Majority/majority (W=R=2 of 3) is the balanced default.\n- Overlap alone is not full linearizability: sloppy quorums, concurrent writes and clock issues still allow stale reads.\n- Read repair and anti-entropy fix replicas that missed writes.", "check": "assert overlaps(3, 2, 2) and overlaps(5, 3, 3) and overlaps(3, 1, 3)\nassert not overlaps(3, 1, 1) and not overlaps(5, 2, 3)"},
    {"id": "sd-replication-lag", "title": "Replication lag and its problems", "q": ["what is replication lag", "why do followers lag behind the leader", "problems with async replication", "how to handle stale replicas", "replica lag read anomalies"], "tags": "replication lag stale follower asynchronous monotonic reads failover data loss", "see": ["#/system-design/fundamentals/replication-sharding"], "a": "Replication lag is the delay between a write on the leader and its appearance on a follower. It causes **stale reads, users not seeing their own writes, and time going backwards between two reads**, and a failover can lose writes that hadn't replicated. Mitigate with leader reads after writes, sticky replica routing, lag-aware routing and monitoring.", "more": "- Cause: slow follower, big transaction, network, or a read-heavy replica starving apply threads.\n- Monitor lag in seconds and bytes; alert and remove lagging replicas from the read pool.\n- Semi-sync replication (one synchronous follower) limits data loss on failover.\n- Design the UI for it: show your own edits locally while they replicate."},
    {"id": "sd-sharding", "title": "Sharding (partitioning): range, hash and directory", "q": ["what is sharding", "database partitioning explained", "range vs hash partitioning", "how to shard a database", "directory based sharding", "how do i choose a shard key"], "tags": "sharding partitioning range hash directory shard key horizontal scale split database", "see": ["#/system-design/fundamentals/replication-sharding"], "a": "Sharding splits data across machines so each holds a slice. **Range** sharding keeps neighbours together (good for range scans, risks hot ranges like \"newest timestamp\"). **Hash** sharding spreads keys evenly (kills range scans). **Directory** sharding uses a lookup table from key to shard (flexible, but the directory is a dependency). Choose a shard key with high cardinality that your hot queries include.", "more": "- A bad key causes hot shards: sharding by timestamp sends all writes to one shard.\n- Cross-shard queries and transactions are slow and complex; model data so common operations hit one shard.\n- Replicate each shard for availability, shard for capacity.\n- Use consistent hashing or many small fixed partitions to make resharding cheap."},
    {"id": "sd-hot-key", "title": "Hot keys and hot partitions", "q": ["what is a hot key", "how to handle a hot partition", "celebrity problem in sharding", "one shard gets all the traffic", "hot spot in database"], "tags": "hot key hot partition hot shard skew celebrity salting replicate cache split", "see": ["#/system-design/fundamentals/replication-sharding"], "a": "A hot key is one key (a viral link, a celebrity, a flash-sale item) that gets so much traffic one shard saturates even though total load is fine. Fixes: **cache it in front (and in local memory), replicate it to several nodes, or split it by adding a random suffix (salting)** and aggregating on read; for writes, batch or shard counters.", "more": "- Detect with per-key metrics, not just per-node averages.\n- Read-hot: replicas, local caches, CDN. Write-hot: salted sub-keys (`item:42#0..#9`) summed on read, or buffer and batch.\n- Hash sharding doesn't help; one key still maps to one node.\n- Request coalescing stops a cold hot key from stampeding the database."},
    {"id": "sd-resharding", "title": "How to reshard without downtime", "q": ["how do you reshard a database", "add more shards without downtime", "rebalancing partitions", "too many shards or too few", "how to add a node to a sharded cluster"], "tags": "resharding rebalancing partitions virtual shards split migrate dual write online", "see": ["#/system-design/fundamentals/replication-sharding", "#/system-design/fundamentals/consistent-hashing"], "a": "Avoid `hash(key) % N`, because changing N moves almost every key. Use **many fixed small partitions (e.g. 1,024) mapped to nodes**, or consistent hashing, so adding a node just moves a few partitions. Migrate online: copy a partition, stream changes, switch the routing entry, then delete the old copy.", "more": "- Steps: create the new owner, copy a snapshot, replay the change log until caught up, flip the route atomically, clean up.\n- Throttle copying so production traffic isn't hurt.\n- Over-partition from day one; splitting a partition later is harder than moving whole ones.\n- Keep the key-to-partition mapping in a small consistent store (config service)."},
    {"id": "sd-consistent-hashing", "title": "Consistent hashing with virtual nodes", "q": ["how does consistent hashing work", "consistent hashing explained", "implement consistent hashing", "hash ring with virtual nodes python", "why consistent hashing", "consistent hash ring"], "tags": "consistent hashing hash ring virtual nodes vnodes bisect shard cache distributed", "see": ["#/system-design/fundamentals/consistent-hashing", "#/system-design/distributed-kv-store"], "a": "Hash both nodes and keys onto the same circular space; **a key belongs to the first node clockwise from it**. Adding or removing a node only moves the keys next to it (about 1/N of them) instead of reshuffling everything like `hash % N`. Virtual nodes (each server placed at many ring positions) even out load.", "code": {"py": "import bisect, hashlib\n\nclass HashRing:\n    def __init__(self, nodes=(), vnodes=100):\n        self.vnodes, self.ring, self.keys = vnodes, {}, []   # position -> node, sorted positions\n        for n in nodes:\n            self.add(n)\n\n    def _h(self, s):\n        return int(hashlib.md5(s.encode()).hexdigest(), 16)\n\n    def add(self, node):\n        for i in range(self.vnodes):\n            pos = self._h(f\"{node}#{i}\")\n            self.ring[pos] = node\n            bisect.insort(self.keys, pos)\n\n    def remove(self, node):\n        for i in range(self.vnodes):\n            pos = self._h(f\"{node}#{i}\")\n            del self.ring[pos]\n            self.keys.remove(pos)\n\n    def get(self, key):\n        i = bisect.bisect(self.keys, self._h(key)) % len(self.keys)   # wrap around\n        return self.ring[self.keys[i]]\n\nring = HashRing([\"a\", \"b\", \"c\"])\nprint(ring.get(\"user:42\"))"}, "more": "- Lookup is O(log V) by binary search over V ring positions.\n- More virtual nodes means smoother balance and a bigger ring table; give bigger machines more vnodes.\n- Replication: also store on the next R-1 distinct nodes clockwise.\n- Used by Dynamo-style stores, cache clusters and CDNs.", "cx": "lookup O(log V); add or remove a node moves about K/N keys", "check": "ring = HashRing([\"a\", \"b\", \"c\"])\nkeys = [f\"k{i}\" for i in range(3000)]\nbefore = {k: ring.get(k) for k in keys}\nassert set(before.values()) == {\"a\", \"b\", \"c\"}\nring.add(\"d\")\nmoved = sum(before[k] != ring.get(k) for k in keys)\nassert all(ring.get(k) == \"d\" for k in keys if before[k] != ring.get(k))   # keys only move to the new node\nassert 0.1 * len(keys) < moved < 0.45 * len(keys)                       # roughly 1/4 move, not all\nring.remove(\"d\")\nassert {k: ring.get(k) for k in keys} == before"},
    {"id": "sd-hash-mod-n-problem", "title": "Why not use hash(key) % N?", "q": ["why not hash mod n for sharding", "problem with modulo hashing when adding servers", "what happens to keys when a node is added", "hash key mod number of servers"], "tags": "modulo hash mod n rehash remap resharding cache miss consistent hashing", "see": ["#/system-design/fundamentals/consistent-hashing"], "a": "With `hash(key) % N`, changing N changes the owner of almost every key (going from 4 to 5 servers remaps about 80%), so a cache cluster suddenly misses nearly everything and a database must move most of its data. Consistent hashing or fixed virtual partitions move only about 1/N.", "code": {"py": "def moved_fraction(keys, n_old, n_new):\n    return sum(hash(k) % n_old != hash(k) % n_new for k in keys) / len(keys)\n\nprint(moved_fraction(range(10000), 4, 5))   # 0.8"}, "more": "- Fine for a fixed-size cluster that never changes.\n- For caches, the miss storm after resizing can overload the database.", "check": "assert abs(moved_fraction(range(10000), 4, 5) - 0.8) < 0.01\nassert moved_fraction(range(10000), 4, 4) == 0"},
    {"id": "sd-caching-strategies", "title": "Caching strategies: cache-aside, write-through, write-back, write-around", "q": ["what are the caching strategies", "cache aside vs write through", "write back cache explained", "write around cache", "read through cache", "how does caching work in system design"], "tags": "cache aside lazy loading write through write back write behind write around read through redis memcached", "see": ["#/system-design/fundamentals/caching"], "a": "**Cache-aside**: the app checks the cache, on a miss reads the DB and fills the cache (most common). **Write-through**: writes go to cache and DB together, so the cache is always fresh but writes are slower. **Write-back**: writes hit the cache and flush to the DB later (fast, risk of loss). **Write-around**: writes skip the cache and go to the DB, avoiding pollution from rarely read data.", "more": "- Read-through is cache-aside where the cache library does the DB load itself.\n- On update with cache-aside, prefer deleting the key over setting it, to avoid races that leave stale values.\n- Add a TTL as a safety net even when you invalidate explicitly.\n- Write-back needs durability (replicated cache or log) for data you can't lose."},
    {"id": "sd-write-through-vs-back", "title": "Write-through vs write-back caching", "q": ["write through vs write back", "write behind cache risks", "which cache write policy should i use", "difference between write through and write back"], "tags": "write through write back write behind cache durability latency policy", "see": ["#/system-design/fundamentals/caching"], "a": "Use **write-through** when data must not be lost and reads must be fresh (cache and DB are updated together, slower writes). Use **write-back** (write-behind) when you need very fast or batched writes and can accept losing the latest updates if the cache node dies before flushing.", "more": "- Write-through: simple, consistent, doubles write cost, caches data that may never be read.\n- Write-back: coalesces repeated writes to one key, absorbs bursts, but needs a flush queue and recovery after crashes.\n- Hybrid: write-through for critical fields, write-back for counters or view stats."},
    {"id": "sd-cache-eviction", "title": "Cache eviction: LRU, LFU and TTL", "q": ["lru vs lfu", "cache eviction policies", "what is ttl in cache", "which eviction policy to use", "least recently used explained", "how does a cache decide what to remove"], "tags": "eviction lru lfu fifo ttl cache policy least recently used least frequently used", "see": ["#/system-design/fundamentals/cache-eviction"], "a": "When a cache is full it evicts something. **LRU** removes the least recently used key (good general default). **LFU** removes the least often used (keeps long-term popular keys, but old hits can linger). **TTL** expires entries after a time regardless of space, bounding staleness. Most systems combine a size-based policy with a TTL.", "more": "- FIFO is simplest but ignores usage.\n- LRU is hurt by scans that touch lots of keys once; scan-resistant variants (2Q, TinyLFU) fix this.\n- LFU needs frequency decay or it never evicts yesterday's hot keys.\n- Redis uses approximated LRU/LFU by sampling, not exact lists."},
    {"id": "sd-lru-cache-code", "title": "Implement an LRU cache (O(1) get and put)", "q": ["implement lru cache in python", "how to build an lru cache", "lru cache with ordereddict", "design lru cache", "least recently used cache code"], "tags": "lru cache ordereddict move_to_end doubly linked list hash map capacity eviction", "see": ["#/system-design/lld-lru-cache", "#/system-design/fundamentals/cache-eviction"], "a": "Use a hash map plus a doubly linked list so both lookup and \"mark most recent\" are O(1). In Python, `OrderedDict` already is exactly that: `move_to_end` on every access and `popitem(last=False)` to evict the oldest.", "code": {"py": "from collections import OrderedDict\n\nclass LRUCache:\n    def __init__(self, capacity):\n        self.cap, self.d = capacity, OrderedDict()\n\n    def get(self, key):\n        if key not in self.d:\n            return -1\n        self.d.move_to_end(key)          # now most recently used\n        return self.d[key]\n\n    def put(self, key, value):\n        self.d[key] = value\n        self.d.move_to_end(key)\n        if len(self.d) > self.cap:\n            self.d.popitem(last=False)   # evict least recently used\n\nc = LRUCache(2)\nc.put(1, 1); c.put(2, 2); c.get(1); c.put(3, 3)\nprint(c.get(2))   # -1, key 2 was evicted"}, "cx": "get and put O(1); space O(capacity)", "check": "c = LRUCache(2)\nc.put(1, 1); c.put(2, 2)\nassert c.get(1) == 1\nc.put(3, 3)\nassert c.get(2) == -1 and c.get(3) == 3 and c.get(1) == 1\nc.put(1, 10)\nassert c.get(1) == 10\nassert LRUCache(1).get(5) == -1"},
    {"id": "sd-cache-stampede", "title": "Cache stampede (thundering herd) and how to prevent it", "q": ["what is a cache stampede", "thundering herd cache", "hot key expires and database overloaded", "how to prevent dogpile effect", "request coalescing"], "tags": "cache stampede thundering herd dogpile single flight lock jitter ttl early refresh stale while revalidate", "see": ["#/system-design/fundamentals/cache-eviction"], "a": "A stampede happens when a popular key expires (or the cache is cold) and many requests miss at once and all hit the database. Prevent it with **request coalescing (one request rebuilds, others wait)**, **TTL jitter** so keys don't expire together, **early/background refresh** and serving stale while refreshing.", "more": "- Coalescing: a per-key lock or single-flight in the app; a short-lived Redis lock across servers.\n- Jitter: `ttl = base + random(0, 10%)`.\n- Negative caching: cache \"not found\" briefly so missing keys can't hammer the DB.\n- Warm the cache before a launch or after a restart."},
    {"id": "sd-cache-invalidation", "title": "Cache invalidation strategies", "q": ["how to invalidate a cache", "cache invalidation is hard why", "keeping cache in sync with database", "ttl vs explicit invalidation", "stale cache problem"], "tags": "cache invalidation ttl delete on write stale versioned keys event cdc purge", "see": ["#/system-design/fundamentals/cache-eviction"], "a": "Three tools: **TTL** (accept bounded staleness), **explicit delete on write** (delete the key after updating the DB, so the next read refills it), and **event-driven invalidation** (publish change events or read the DB change log). Delete rather than set on update, and keep a TTL as a safety net.", "more": "- Race with set-on-update: two writers can leave the older value cached; deleting avoids most of this.\n- Versioned keys (`user:42:v7`) or content hashes make invalidation unnecessary for immutable assets.\n- Layers (browser, CDN, app cache) each need their own plan; CDNs support purge by key or prefix.\n- Delete-then-update ordering still has a small race; TTL bounds the damage."},
    {"id": "sd-cdn", "title": "What is a CDN and how does it work?", "q": ["what is a cdn", "how does a content delivery network work", "cdn push vs pull", "when to use a cdn", "cdn cache miss origin"], "tags": "cdn content delivery network edge pop origin pull push cache ttl static assets video", "see": ["#/system-design/fundamentals/cdn"], "a": "A CDN is a network of edge servers near users that cache copies of your content. A request goes to the nearest edge; on a **hit** it is served immediately, on a **miss** the edge fetches from your origin, caches it and serves it. It cuts latency, offloads the origin and absorbs traffic spikes.", "more": "- Pull CDN: edge fetches on first request (easy). Push: you upload content ahead (good for big, rarely changing files).\n- Control freshness with `Cache-Control` TTLs, versioned filenames (`app.3f9a.js`), or purge APIs.\n- Best for static assets, images, video segments and cacheable API responses.\n- Watch hit ratio and egress cost; an origin shield reduces origin load."},
    {"id": "sd-load-balancing-algorithms", "title": "Load balancing algorithms", "q": ["load balancing algorithms", "round robin vs least connections", "how does a load balancer pick a server", "weighted round robin", "consistent hash load balancing", "ip hash"], "tags": "load balancer round robin least connections weighted ip hash consistent hash random power of two choices", "see": ["#/system-design/fundamentals/load-balancing"], "a": "**Round robin** cycles through servers (fine when requests are similar). **Least connections** sends to the server with the fewest active requests (better when request cost varies). **Weighted** variants favour bigger machines. **Hashing** (by client IP or key, ideally consistent hashing) gives affinity, e.g. for caches. \"Power of two choices\" (pick 2 at random, take the less loaded) is cheap and works well.", "more": "- Sticky sessions pin a user to a server; avoid by keeping servers stateless.\n- Slow-start new servers so they don't get flooded.\n- Least-connections needs load info; round robin needs none."},
    {"id": "sd-l4-vs-l7", "title": "Layer 4 vs Layer 7 load balancing", "q": ["l4 vs l7 load balancer", "layer 4 vs layer 7", "what is a layer 7 load balancer", "transport vs application load balancing", "when to use l7"], "tags": "l4 l7 load balancer tcp http transport application layer routing tls termination", "see": ["#/system-design/fundamentals/load-balancing"], "a": "An **L4** balancer routes TCP/UDP connections by IP and port without reading the payload: very fast and simple. An **L7** balancer parses HTTP, so it can route by path, host, header or cookie, terminate TLS, retry and rewrite. Use L7 when you need content-based routing; L4 for raw throughput or non-HTTP protocols. Large systems often put an L4 layer in front of L7.", "more": "- L7 costs more CPU per request but enables canary releases, A/B routing and per-route limits.\n- L4 sees only connections, so it balances connections, not individual requests (matters for long-lived HTTP/2 or gRPC).\n- Both need health checks and redundancy so the balancer isn't a single point of failure."},
    {"id": "sd-health-checks", "title": "Health checks in load balancers", "q": ["what is a health check", "load balancer health check", "liveness vs readiness", "how does a load balancer know a server is down", "active vs passive health checks"], "tags": "health check liveness readiness active passive load balancer eject threshold", "see": ["#/system-design/fundamentals/load-balancing"], "a": "A health check lets the load balancer stop sending traffic to a bad server. **Active** checks probe an endpoint (e.g. `GET /healthz`) every few seconds; **passive** checks watch real traffic for errors and timeouts. Eject after several consecutive failures and re-admit after several successes, to avoid flapping.", "more": "- Liveness: process is alive (restart if not). Readiness: can serve traffic now (warm, dependencies reachable).\n- Keep checks cheap; don't let a shared dependency outage mark every server unhealthy at once.\n- Drain connections before removing a server for deploys."},
    {"id": "sd-reverse-proxy", "title": "Reverse proxy vs forward proxy", "q": ["what is a reverse proxy", "reverse proxy vs load balancer", "forward proxy vs reverse proxy", "nginx reverse proxy purpose"], "tags": "reverse proxy forward proxy nginx haproxy tls termination caching compression load balancer", "see": ["#/system-design/fundamentals/load-balancing"], "a": "A **reverse proxy** sits in front of servers and handles requests on their behalf: TLS termination, caching, compression, routing and load balancing. A **forward proxy** sits in front of clients and fetches things for them (anonymity, filtering). A load balancer is a reverse proxy focused on spreading traffic.", "more": "- Benefits: hides internal topology, one place for TLS/auth/limits, shields apps from slow clients.\n- Examples: nginx, HAProxy, Envoy.\n- An API gateway is a reverse proxy with API-specific features (auth, rate limits, routing)."},
    {"id": "sd-api-gateway", "title": "What is an API gateway?", "q": ["what is an api gateway", "api gateway responsibilities", "api gateway vs load balancer", "do i need an api gateway", "bff pattern"], "tags": "api gateway routing auth rate limiting request aggregation microservices edge", "see": ["#/system-design/rate-limiter", "#/system-design/fundamentals/load-balancing"], "a": "An API gateway is the single entry point for clients in front of many services. It handles **routing, authentication, rate limiting, TLS, request/response transformation, logging and sometimes aggregation** so each service doesn't repeat that. Keep business logic out of it, and run several instances because it is on every request path.", "more": "- Differs from a plain load balancer by being API-aware (per-route policy, per-key limits).\n- Risk: becomes a bottleneck or a god-service if overloaded with logic.\n- A \"backend for frontend\" is a gateway tailored per client type (web, mobile)."},
    {"id": "sd-queue-vs-stream", "title": "Message queue vs log stream (Kafka-style)", "q": ["message queue vs kafka", "how does kafka work", "what is a partitioned log", "sqs vs kafka", "queue vs event stream", "consumer groups"], "tags": "kafka queue stream log partition offset consumer group sqs rabbitmq retention replay", "see": ["#/system-design/fundamentals/queues-pubsub"], "a": "A **queue** (SQS, RabbitMQ) hands each message to one worker and deletes it after acknowledgement: good for task distribution. A **log stream** (Kafka) appends messages to partitioned, retained logs; consumers track their own **offset**, so many independent consumer groups can read and **replay** the same data. Order is guaranteed only within a partition.", "more": "- Producers choose the partition by key, so all events for one key stay in order.\n- A consumer group splits partitions among its members; max parallelism = number of partitions.\n- Use a queue for jobs, a log for event sourcing, analytics feeds and fan-out to many systems.\n- Retention is by time or size, not by consumption."},
    {"id": "sd-delivery-semantics", "title": "At-most-once, at-least-once and exactly-once delivery", "q": ["at least once vs at most once vs exactly once", "what is exactly once delivery", "message delivery guarantees", "how to avoid duplicate messages", "kafka exactly once"], "tags": "delivery semantics at most once at least once exactly once idempotent consumer dedupe ack retry", "see": ["#/system-design/fundamentals/queues-pubsub", "#/system-design/payment-system"], "a": "**At-most-once**: send and don't retry; may lose messages. **At-least-once**: retry until acknowledged; no loss but duplicates. **Exactly-once delivery** isn't achievable end to end over an unreliable network; what systems offer is **at-least-once delivery plus idempotent processing**, giving exactly-once *effects*. Default to at-least-once and make consumers idempotent.", "more": "- Duplicates happen when the ack is lost or the consumer crashes after doing work but before acking.\n- Idempotent consumer: record processed message IDs, or make the operation naturally idempotent (set, not increment).\n- Kafka's \"exactly-once\" covers read-process-write within Kafka via transactions and idempotent producers."},
    {"id": "sd-idempotency-keys", "title": "Idempotency keys: make retries safe", "q": ["what is an idempotency key", "how to make an api idempotent", "avoid double charge on retry", "idempotent post request", "implement idempotency"], "tags": "idempotency key idempotent retry duplicate payment dedupe stripe request id", "see": ["#/system-design/payment-system", "#/system-design/fundamentals/queues-pubsub"], "a": "The client generates a unique key per logical operation and sends it with every retry. The server **stores the key with the result; if it sees the key again, it returns the saved result instead of doing the work again.** Claim the key atomically (unique constraint) before acting so two concurrent retries can't both run.", "code": {"py": "class IdempotentService:\n    def __init__(self):\n        self.results = {}            # in production: a DB table with a unique key\n        self.charges = 0\n\n    def charge(self, key, amount):\n        if key in self.results:      # retry: return the stored answer\n            return self.results[key]\n        self.charges += 1            # the real side effect, done once\n        result = {\"charged\": amount, \"id\": self.charges}\n        self.results[key] = result\n        return result\n\nsvc = IdempotentService()\nr1 = svc.charge(\"order-9\", 50)\nr2 = svc.charge(\"order-9\", 50)       # client retried after a timeout\nprint(r1 == r2, svc.charges)         # True 1"}, "more": "- Store the request fingerprint too, and reject the same key with a different body.\n- Expire keys after a window (e.g. 24 hours).\n- If the first attempt is still running, return \"in progress\" or wait.", "check": "svc = IdempotentService()\nassert svc.charge(\"a\", 5) == svc.charge(\"a\", 5)\nassert svc.charges == 1\nsvc.charge(\"b\", 7)\nassert svc.charges == 2"},
    {"id": "sd-pubsub", "title": "Publish/subscribe (pub/sub) pattern", "q": ["what is pub sub", "publish subscribe pattern explained", "pub sub vs queue", "topics and subscribers", "fan out messaging"], "tags": "pub sub publish subscribe topic subscriber fan out event bus sns decoupling", "see": ["#/system-design/fundamentals/queues-pubsub"], "a": "Publishers send messages to a **topic** without knowing who listens; every subscriber to that topic gets its own copy. It decouples producers from consumers and enables fan-out (one \"order placed\" event feeding billing, email and analytics). A queue delivers each message to one consumer; pub/sub delivers to all subscribers.", "more": "- Each subscriber usually has its own queue or offset so a slow one doesn't block others.\n- Consider ordering, retries, dead-letter queues and schema versioning.\n- Watch for event storms and hidden coupling through event contracts.\n- Examples: SNS+SQS, Google Pub/Sub, Kafka topics."},
    {"id": "sd-rate-limit-algorithms", "title": "Rate limiting algorithms compared", "q": ["rate limiting algorithms", "token bucket vs leaky bucket", "fixed window vs sliding window", "which rate limiter algorithm should i use", "sliding window log vs counter"], "tags": "rate limiting token bucket leaky bucket fixed window sliding window log counter throttle 429", "see": ["#/system-design/fundamentals/rate-limiting", "#/system-design/rate-limiter"], "a": "**Token bucket**: tokens refill at a steady rate up to a cap; each request spends one (allows bursts, the usual default). **Leaky bucket**: requests queue and drain at a fixed rate (smooth output). **Fixed window**: count per calendar window (simple, but allows 2x at window edges). **Sliding window log**: store timestamps (exact, memory-heavy). **Sliding window counter**: weight the previous window (cheap, approximate).", "more": "- Token bucket needs 2 numbers per key (tokens, last refill time), so it is cheap in Redis.\n- Fixed window edge problem: 100 requests at 12:00:59 plus 100 at 12:01:00 all pass.\n- Do the check atomically (Redis Lua script or `INCR`) so concurrent servers share one count.\n- Reject with HTTP 429 and `Retry-After`."},
    {"id": "sd-token-bucket-code", "title": "Implement a token bucket rate limiter", "q": ["token bucket implementation python", "implement rate limiter in python", "how does a token bucket work", "token bucket algorithm code", "allow bursts rate limit"], "tags": "token bucket rate limiter python refill capacity burst algorithm allow", "see": ["#/system-design/rate-limiter", "#/system-design/fundamentals/rate-limiting"], "a": "Keep `tokens` and the last refill time. On each request, add `elapsed * rate` tokens (capped at capacity), then allow the request only if at least one token is available and spend it. No background timer is needed: refill lazily on access.", "code": {"py": "import time\n\nclass TokenBucket:\n    def __init__(self, rate, capacity, now=time.monotonic):\n        self.rate, self.capacity, self.now = rate, capacity, now   # rate = tokens per second\n        self.tokens, self.last = capacity, now()\n\n    def allow(self, cost=1):\n        t = self.now()\n        self.tokens = min(self.capacity, self.tokens + (t - self.last) * self.rate)\n        self.last = t\n        if self.tokens >= cost:\n            self.tokens -= cost\n            return True\n        return False\n\nclock = [0.0]\ntb = TokenBucket(rate=2, capacity=5, now=lambda: clock[0])\nprint([tb.allow() for _ in range(6)])   # five True (burst), then False"}, "more": "- One bucket per client key, stored in Redis with a Lua script so read-modify-write is atomic.\n- Allowed average rate = refill rate; allowed burst = capacity.\n- Pass an injectable clock so tests don't sleep.", "cx": "O(1) time and space per key", "check": "clock = [0.0]\ntb = TokenBucket(rate=2, capacity=5, now=lambda: clock[0])\nassert [tb.allow() for _ in range(6)] == [True] * 5 + [False]\nclock[0] += 1.0                       # 1 second -> 2 tokens\nassert tb.allow() and tb.allow() and not tb.allow()\nclock[0] += 100                       # long idle never exceeds capacity\nassert sum(tb.allow() for _ in range(10)) == 5"},
    {"id": "sd-sliding-window-counter-code", "title": "Implement a sliding window counter rate limiter", "q": ["sliding window counter implementation", "sliding window rate limiter python", "how does sliding window counter work", "avoid fixed window burst problem", "approximate sliding window"], "tags": "sliding window counter rate limiter python previous window weighted approximate fixed window", "see": ["#/system-design/rate-limiter", "#/system-design/fundamentals/rate-limiting"], "a": "Keep a count for the current and previous fixed window. Estimate the sliding count as `prev * (1 - fraction of current window elapsed) + curr`, and allow if it is below the limit. It uses two counters per key and avoids the double-burst of fixed windows, at the cost of a small approximation.", "code": {"py": "class SlidingWindowCounter:\n    def __init__(self, limit, window):\n        self.limit, self.window = limit, window\n        self.cur_start, self.cur, self.prev = 0, 0, 0\n\n    def allow(self, now):\n        start = now - now % self.window\n        if start != self.cur_start:\n            # previous window only counts if it is directly adjacent\n            self.prev = self.cur if start - self.cur_start == self.window else 0\n            self.cur, self.cur_start = 0, start\n        frac = (now - start) / self.window\n        if self.prev * (1 - frac) + self.cur + 1 > self.limit:\n            return False\n        self.cur += 1\n        return True\n\nrl = SlidingWindowCounter(limit=10, window=60)\nprint(sum(rl.allow(50) for _ in range(20)))   # 10"}, "more": "- Fixed window would allow 10 at t=50 and another 10 at t=61; this blocks that.\n- Assumes requests were evenly spread across the previous window; error is small in practice.\n- Sliding window log is exact but stores one timestamp per request.", "cx": "O(1) time, two counters per key", "check": "rl = SlidingWindowCounter(limit=10, window=60)\nassert sum(rl.allow(50) for _ in range(20)) == 10\n# right after the window rolls over, the old burst still counts almost fully\nassert not rl.allow(61)\n# half way through the next window, half of the old count has aged out\nassert sum(rl.allow(90) for _ in range(20)) == 5\nrl2 = SlidingWindowCounter(3, 10)\nassert [rl2.allow(0) for _ in range(4)] == [True, True, True, False]"},
    {"id": "sd-two-phase-commit-vs-saga", "title": "Two-phase commit vs saga", "q": ["2pc vs saga", "what is two phase commit", "saga pattern explained", "distributed transactions across microservices", "how to do a transaction across services", "compensating transactions"], "tags": "two phase commit 2pc saga distributed transaction compensating coordinator orchestration choreography", "see": ["#/system-design/payment-system", "#/system-design/ticket-booking"], "a": "**Two-phase commit** has a coordinator ask all participants to prepare (lock and vote), then commit or abort everywhere: atomic, but blocking if the coordinator dies and holds locks across services. A **saga** runs a chain of local transactions, and if one fails it runs **compensating actions** (refund, release) for the earlier steps: no global locks, but only eventual consistency. Prefer sagas across services, 2PC inside one database cluster.", "more": "- Saga steps must be idempotent and retryable; compensations must be too.\n- Orchestration: a central coordinator drives steps. Choreography: services react to each other's events.\n- Intermediate states are visible (order \"pending\"), so model them explicitly.\n- Booking example: reserve seat, charge card; if the charge fails, release the seat."},
    {"id": "sd-distributed-lock", "title": "Distributed locks and fencing tokens", "q": ["how do distributed locks work", "redis lock redlock problems", "what is a fencing token", "lock with expiry safe", "distributed mutex"], "tags": "distributed lock fencing token redis lease zookeeper etcd mutual exclusion expiry", "see": ["#/system-design/ticket-booking"], "a": "A distributed lock gives one client exclusive access across machines, usually as a **lease** with an expiry in Redis, etcd or ZooKeeper. Leases can expire while the holder is paused (GC, network), so two clients may both think they hold it. A **fencing token**, an increasing number issued with each lock grant and checked by the resource, rejects writes from the stale holder.", "more": "- Redis `SET key id NX PX 30000` acquires; release with a script that checks the id.\n- Prefer strongly consistent stores (etcd, ZooKeeper) for correctness-critical locks.\n- Often a database conditional update (`UPDATE ... WHERE status='free'`) or optimistic version check is simpler and safer than a lock.\n- Always set an expiry so a crashed holder doesn't block everyone."},
    {"id": "sd-leader-election", "title": "Leader election", "q": ["how does leader election work", "why do we need a leader in distributed systems", "leader election with zookeeper etcd", "bully algorithm", "split brain"], "tags": "leader election consensus lease zookeeper etcd raft split brain term failover", "see": ["#/system-design/distributed-kv-store"], "a": "Leader election picks one node to coordinate (accept writes, schedule jobs) and picks a new one if it dies. The safe way is to use a consensus store (etcd, ZooKeeper, Raft inside the system): nodes compete for a **lease or ephemeral key**, and a majority vote ensures only one wins. Each leadership has an increasing **term/epoch** so old leaders can be fenced out.", "more": "- Split brain (two leaders) is the danger; majority quorums make it impossible for both sides of a partition to elect.\n- Leader leases must be renewed; a leader that can't renew steps down.\n- Simple designs: a DB row with a lease timestamp, updated with compare-and-set."},
    {"id": "sd-raft", "title": "Raft consensus in one paragraph", "q": ["what is raft", "raft consensus explained", "how does raft work", "raft leader election and log replication", "consensus algorithm explained"], "tags": "raft consensus leader election log replication term majority appendentries replicated state machine", "see": ["#/system-design/distributed-kv-store"], "a": "Raft keeps a replicated log consistent across nodes. One node is **leader** per **term**; followers that hear no heartbeat start an election after a randomized timeout and need votes from a **majority**. The leader appends client commands to its log, replicates them with AppendEntries, and **commits an entry once a majority has stored it**, after which every node applies it in order to its state machine.", "more": "- A cluster of 2f+1 nodes survives f failures (3 nodes tolerate 1, 5 tolerate 2).\n- Only candidates with an up-to-date log can win, so committed entries are never lost.\n- Followers reject entries that don't match their log, so logs converge to the leader's.\n- Used in etcd, Consul and many databases."},
    {"id": "sd-paxos", "title": "Paxos in one paragraph", "q": ["what is paxos", "paxos explained simply", "paxos vs raft", "how does paxos reach consensus", "proposers acceptors learners"], "tags": "paxos consensus proposer acceptor learner prepare promise accept quorum", "see": ["#/system-design/distributed-kv-store"], "a": "Paxos lets a group agree on a single value despite failures. A proposer sends **prepare(n)** with a ballot number; acceptors **promise** to ignore lower ballots and report any value they already accepted. With promises from a majority, the proposer sends **accept(n, v)** (using the highest previously accepted value if any), and the value is chosen once a majority accepts it. Raft is a more understandable design for the same problem.", "more": "- Safety holds always; liveness needs a stable leader (dueling proposers can livelock).\n- Multi-Paxos reuses a leader to agree on a sequence of values (a log).\n- Majority quorums guarantee any two quorums overlap, so a chosen value is seen by later proposers."},
    {"id": "sd-gossip", "title": "Gossip protocol", "q": ["what is a gossip protocol", "how do nodes detect failures in a cluster", "gossip membership", "epidemic protocol", "cassandra gossip"], "tags": "gossip epidemic membership failure detection heartbeat cluster state propagation", "see": ["#/system-design/distributed-kv-store"], "a": "In gossip, each node periodically picks a few random peers and exchanges what it knows (membership, heartbeats, state). Information spreads like an epidemic, reaching all N nodes in about O(log N) rounds, with no central coordinator. It's used for cluster membership and failure detection in Dynamo-style systems such as Cassandra.", "more": "- Failure detection: a node whose heartbeat counter hasn't advanced for a while is suspected, then declared down.\n- Scales well and tolerates failures; the cost is eventual, not instant, knowledge.\n- Tune the interval and fan-out to trade detection speed for network traffic."},
    {"id": "sd-vector-clocks", "title": "Vector clocks", "q": ["what is a vector clock", "vector clocks vs lamport clocks", "how to detect concurrent writes", "version vectors dynamo", "last write wins problem"], "tags": "vector clock version vector lamport causality concurrent conflict last write wins dynamo", "see": ["#/system-design/distributed-kv-store", "#/system-design/fundamentals/consistency-models"], "a": "A vector clock stores one counter per node alongside each value. Comparing two clocks tells you if one write **happened-before** the other (all counters less or equal) or if they are **concurrent** (neither dominates), in which case the store keeps both versions as siblings for the app or a merge rule to resolve. Last-write-wins uses wall-clock time instead, which is simple but silently drops one concurrent write.", "code": {"py": "def compare(a, b):\n    \"\"\"Vector clocks as dicts node -> counter. Returns 'before', 'after', 'equal' or 'concurrent'.\"\"\"\n    nodes = set(a) | set(b)\n    le = all(a.get(n, 0) <= b.get(n, 0) for n in nodes)\n    ge = all(a.get(n, 0) >= b.get(n, 0) for n in nodes)\n    if le and ge: return \"equal\"\n    if le: return \"before\"\n    if ge: return \"after\"\n    return \"concurrent\"\n\nprint(compare({\"A\": 1}, {\"A\": 2}))               # before\nprint(compare({\"A\": 2, \"B\": 0}, {\"A\": 1, \"B\": 1}))  # concurrent"}, "more": "- A Lamport clock is a single counter: it orders events consistently but cannot tell concurrent from ordered.\n- Clocks grow with the number of writers; stores prune them.", "check": "assert compare({\"A\": 1}, {\"A\": 2}) == \"before\"\nassert compare({\"A\": 2}, {\"A\": 1}) == \"after\"\nassert compare({\"A\": 2, \"B\": 0}, {\"A\": 1, \"B\": 1}) == \"concurrent\"\nassert compare({}, {}) == \"equal\""},
    {"id": "sd-crdt", "title": "CRDTs (conflict-free replicated data types)", "q": ["what is a crdt", "how do crdts work", "g-counter crdt", "collaborative editing conflict free", "merge without coordination"], "tags": "crdt conflict free replicated data type g counter or set merge convergence collaborative editing", "see": ["#/system-design/fundamentals/consistency-models"], "a": "A CRDT is a data structure whose replicas can be updated independently and merged in any order, any number of times, and still converge to the same state, because the merge is commutative, associative and idempotent. Example: a G-counter keeps one count per node and merges with an element-wise max; the value is the sum.", "code": {"py": "class GCounter:\n    def __init__(self, node):\n        self.node, self.counts = node, {}\n\n    def inc(self, n=1):\n        self.counts[self.node] = self.counts.get(self.node, 0) + n\n\n    def value(self):\n        return sum(self.counts.values())\n\n    def merge(self, other):\n        for k, v in other.counts.items():\n            self.counts[k] = max(self.counts.get(k, 0), v)\n\na, b = GCounter(\"a\"), GCounter(\"b\")\na.inc(2); b.inc(3)\na.merge(b); b.merge(a); a.merge(b)   # merge order and repeats don't matter\nprint(a.value(), b.value())          # 5 5"}, "more": "- Others: PN-counter (inc and dec), OR-set (add/remove), sequence CRDTs for text editing.\n- Trade-off: only operations with a well-defined merge; metadata can grow.", "check": "a, b = GCounter(\"a\"), GCounter(\"b\")\na.inc(2); b.inc(3)\na.merge(b); b.merge(a); a.merge(b)\nassert a.value() == b.value() == 5\na.merge(a)\nassert a.value() == 5"},
    {"id": "sd-bloom-filter-code", "title": "Bloom filter: what it is and a Python implementation", "q": ["what is a bloom filter", "implement a bloom filter in python", "bloom filter false positives", "probabilistic set membership", "how big should a bloom filter be"], "tags": "bloom filter probabilistic membership false positive bit array hash functions crawler cache", "see": ["#/system-design/web-crawler"], "a": "A Bloom filter is a compact bit array answering \"have I seen this?\" with **no false negatives but a tunable rate of false positives**. Adding sets k bits (from k hashes); checking returns \"maybe\" only if all k bits are set. For n items and error rate p, use `m = -n ln p / (ln 2)^2` bits and `k = (m/n) ln 2` hashes. You can't delete items (use a counting Bloom filter for that).", "code": {"py": "import math, hashlib\n\nclass BloomFilter:\n    def __init__(self, n, p=0.01):\n        self.m = max(8, int(-n * math.log(p) / math.log(2) ** 2))\n        self.k = max(1, round(self.m / n * math.log(2)))\n        self.bits = bytearray((self.m + 7) // 8)\n\n    def _positions(self, item):\n        h = hashlib.sha256(str(item).encode()).digest()\n        h1 = int.from_bytes(h[:8], \"big\")\n        h2 = int.from_bytes(h[8:16], \"big\") | 1\n        return [(h1 + i * h2) % self.m for i in range(self.k)]   # double hashing\n\n    def add(self, item):\n        for pos in self._positions(item):\n            self.bits[pos // 8] |= 1 << (pos % 8)\n\n    def __contains__(self, item):\n        return all(self.bits[pos // 8] >> (pos % 8) & 1 for pos in self._positions(item))\n\nbf = BloomFilter(1000, 0.01)\nfor i in range(1000):\n    bf.add(f\"url{i}\")\nprint(\"url5\" in bf, \"other\" in bf)   # True False (almost surely)"}, "more": "- About 9.6 bits per item at 1% false positives.\n- Uses: crawler \"URL seen\" check, skipping disk lookups for missing keys (LSM trees), cache-penetration guards.\n- If it says no, trust it; if it says yes, verify with the real store.", "cx": "add and query O(k); space O(m) bits", "check": "bf = BloomFilter(1000, 0.01)\nfor i in range(1000):\n    bf.add(f\"url{i}\")\nassert all(f\"url{i}\" in bf for i in range(1000))          # no false negatives\nfp = sum(f\"nope{i}\" in bf for i in range(10000)) / 10000\nassert fp < 0.03, fp                                       # near the 1% target"},
    {"id": "sd-hyperloglog", "title": "HyperLogLog: counting unique items in tiny memory", "q": ["what is hyperloglog", "count distinct users with little memory", "approximate unique count", "redis pfadd pfcount", "cardinality estimation"], "tags": "hyperloglog hll cardinality distinct count unique visitors approximate redis pfcount sketch", "see": ["#/system-design/video-streaming"], "a": "HyperLogLog estimates the number of **distinct** items using a few KB regardless of how many items you see. It hashes each item and tracks, per bucket, the longest run of leading zero bits seen; rare long runs imply many distinct items. Redis's HLL uses about 12 KB and has roughly 0.8% standard error, and two HLLs can be merged for unions.", "more": "- Use it for unique visitors, distinct searches, or per-video unique viewers where exact counts aren't needed.\n- It can't list the members or remove items, only add, count and merge.\n- Exact counting would need a set growing with the number of distinct items.\n- Redis commands: `PFADD`, `PFCOUNT`, `PFMERGE`."},
    {"id": "sd-lsm-vs-btree", "title": "LSM tree vs B-tree storage engines", "q": ["lsm tree vs b tree", "how does an lsm tree work", "write optimized vs read optimized database", "memtable sstable compaction", "why is cassandra fast at writes"], "tags": "lsm tree b tree memtable sstable compaction write amplification wal rocksdb cassandra postgres", "see": ["#/system-design/fundamentals/databases", "#/system-design/distributed-kv-store"], "a": "A **B-tree** updates pages in place on disk: great for reads and range scans, with random writes. An **LSM tree** buffers writes in a sorted in-memory **memtable** (plus a write-ahead log), flushes it as immutable sorted **SSTable** files, and merges them in background **compaction**: very fast sequential writes, but reads may check several files (Bloom filters help) and compaction adds write amplification.", "more": "- Choose B-tree (Postgres, MySQL/InnoDB) for read-heavy, mixed workloads with point and range queries.\n- Choose LSM (RocksDB, Cassandra, LevelDB) for heavy ingest and write-heavy workloads.\n- Deletes in LSM are tombstones removed at compaction.\n- Both use a WAL for crash safety."},
    {"id": "sd-sql-vs-nosql", "title": "SQL vs NoSQL: which should I pick?", "q": ["sql vs nosql", "when to use nosql", "relational vs non relational database", "which database should i choose", "sql or mongodb"], "tags": "sql nosql relational document key value wide column graph choose database tradeoff joins schema", "see": ["#/system-design/fundamentals/databases"], "a": "Default to **SQL** (Postgres, MySQL) when data is relational, you need joins, transactions and flexible queries, and one primary plus replicas handles the scale. Pick **NoSQL** when you have a clear access pattern at huge scale, a flexible schema, or need easy horizontal sharding and high write rates, and you can live without joins and multi-row transactions.", "more": "- Modern SQL scales far (read replicas, partitioning); don't leave it just because it sounds scalable.\n- NoSQL schema follows queries: you denormalize and store what each query reads.\n- Many systems use both: SQL for orders and money, key-value for sessions/cache, search index for text.\n- Decide by access pattern, consistency need and operations cost."},
    {"id": "sd-nosql-types", "title": "Types of NoSQL databases and when to pick each", "q": ["types of nosql databases", "document vs key value vs wide column vs graph", "when to use mongodb", "when to use cassandra", "when to use a graph database", "redis vs dynamodb"], "tags": "nosql document key value wide column graph mongodb redis dynamodb cassandra neo4j types", "see": ["#/system-design/fundamentals/databases"], "a": "**Key-value** (Redis, DynamoDB): lookup by key at huge speed, for sessions, caches, counters. **Document** (MongoDB): JSON-like records with flexible schema and secondary indexes, for catalogs and profiles. **Wide-column** (Cassandra, Bigtable): partition key plus sorted columns for massive write-heavy time-series and logs. **Graph** (Neo4j): relationships as first-class edges, for social graphs, recommendations and fraud paths.", "more": "- Pick by access pattern: single-key (kv), nested record (document), partition + range scan (wide-column), multi-hop traversal (graph).\n- Wide-column stores need queries designed up front; ad hoc queries are weak.\n- Search engines (Elasticsearch) are a separate category for full-text."},
    {"id": "sd-database-indexes", "title": "Database indexes: how they work and their cost", "q": ["what is a database index", "how do indexes speed up queries", "composite index column order", "why not index every column", "covering index"], "tags": "index b-tree composite covering index write cost selectivity query plan sql", "see": ["#/system-design/fundamentals/databases"], "a": "An index is a separate sorted structure (usually a B-tree) mapping column values to rows, so a lookup is O(log n) instead of a full table scan. It speeds reads but **costs extra storage and slows every write**, since each index must be updated. A composite index `(a, b)` helps queries filtering on `a`, or on `a` and `b`, but not on `b` alone.", "more": "- Index columns used in WHERE, JOIN and ORDER BY on large tables.\n- Covering index: contains every column the query needs, so the table is never touched.\n- Low-selectivity columns (e.g. boolean) rarely help.\n- Check with `EXPLAIN`. Too many indexes hurt write-heavy tables."},
    {"id": "sd-denormalization", "title": "Denormalization: when and why", "q": ["what is denormalization", "normalization vs denormalization", "when to denormalize a database", "duplicate data for read speed", "precomputed counts"], "tags": "denormalization normalization duplicate data read performance joins precompute materialized view tradeoff", "see": ["#/system-design/fundamentals/databases"], "a": "Denormalizing means storing the same data in more than one place (or precomputing it) so reads avoid joins and extra lookups. It makes reads fast and simple at the cost of **more storage and having to keep copies in sync on every write**. Do it when reads far outnumber writes and joins are the bottleneck, or in NoSQL stores where joins don't exist.", "more": "- Examples: store `author_name` in each post, keep `like_count` on the post, a materialized timeline per user.\n- Keep one source of truth and update copies via events or transactions.\n- Accept brief staleness for derived copies, or update synchronously for critical ones."},
    {"id": "sd-isolation-levels", "title": "Database transaction isolation levels", "q": ["isolation levels explained", "read committed vs repeatable read vs serializable", "what is a dirty read", "phantom read", "non repeatable read", "what is snapshot isolation"], "tags": "isolation levels read uncommitted read committed repeatable read serializable dirty read phantom snapshot lost update", "see": ["#/system-design/fundamentals/databases"], "a": "Isolation controls what concurrent transactions can see. **Read committed**: no dirty reads (you only see committed data). **Repeatable read / snapshot**: your reads see one stable snapshot, so repeating a read gives the same rows. **Serializable**: results are as if transactions ran one at a time, preventing phantoms and write skew, at the highest cost. Higher isolation, fewer anomalies, more conflicts or aborts.", "more": "- Dirty read: seeing uncommitted data. Non-repeatable read: a row changes between two reads. Phantom: new rows appear in a repeated range query.\n- Lost update and write skew are avoided with locks (`SELECT ... FOR UPDATE`), version checks, or serializable mode.\n- Defaults vary: Postgres read committed, MySQL InnoDB repeatable read."},
    {"id": "sd-websocket-vs-polling-sse", "title": "WebSockets vs long polling vs SSE", "q": ["websockets vs long polling", "server sent events vs websockets", "how to push updates to the browser", "realtime updates options", "when to use sse"], "tags": "websocket long polling sse server sent events realtime push http polling chat", "see": ["#/system-design/chat", "#/system-design/file-sync"], "a": "**Short polling** asks repeatedly (simple, wasteful). **Long polling** holds a request open until data arrives (works everywhere, extra overhead). **SSE** is a one-way server-to-client stream over HTTP with auto-reconnect (great for feeds and notifications). **WebSockets** are a persistent two-way connection (chat, games, collaboration). Pick the simplest one that fits the direction and frequency of updates.", "more": "- WebSocket servers keep per-connection state, so you need a connection-to-server registry and care on deploys (reconnect storms).\n- SSE works through most proxies and is easy to scale as plain HTTP.\n- Mobile apps often use push notifications when the app is closed."},
    {"id": "sd-rest-grpc-graphql", "title": "REST vs gRPC vs GraphQL", "q": ["rest vs grpc vs graphql", "when to use grpc", "what is graphql good for", "which api style should i use", "protobuf vs json"], "tags": "rest grpc graphql api protobuf json http2 over fetching schema microservices", "see": ["#/system-design/fundamentals/client-server-dns"], "a": "**REST** (HTTP + JSON, resources and verbs) is the simple, cacheable default for public APIs. **gRPC** (HTTP/2 + Protobuf) is compact, fast and strongly typed with streaming, ideal for internal service-to-service calls. **GraphQL** lets the client request exactly the fields it needs from one endpoint, good for varied frontends, but is harder to cache and rate limit.", "more": "- Browsers can't call gRPC directly without a proxy (gRPC-web).\n- GraphQL fixes over/under-fetching but needs query cost limits.\n- REST caches well via HTTP; use idempotent verbs and status codes properly."},
    {"id": "sd-microservices-vs-monolith", "title": "Microservices vs monolith", "q": ["microservices vs monolith", "when to use microservices", "monolith first", "pros and cons of microservices", "modular monolith"], "tags": "microservices monolith modular deployment team independent scaling distributed complexity", "see": ["#/system-design/fundamentals/scaling"], "a": "Start with a **(modular) monolith**: one deployable, simple debugging, local calls, transactions. Move to **microservices** when teams or scaling needs make independent deployment worth the cost: network calls, partial failures, distributed data and tracing. Microservices solve organizational scaling more than technical scaling.", "more": "- Split along business boundaries, each service owning its data; avoid shared databases.\n- Costs: latency, retries and timeouts, versioned APIs, observability, distributed transactions (use sagas).\n- Signs you need to split: teams blocking each other, parts needing very different scaling."},
    {"id": "sd-circuit-breaker", "title": "Circuit breaker pattern", "q": ["what is a circuit breaker", "circuit breaker pattern explained", "closed open half open", "protect service from failing dependency", "fail fast"], "tags": "circuit breaker resilience fail fast closed open half open dependency timeout fallback", "see": ["#/system-design/notification-system"], "a": "A circuit breaker wraps calls to a dependency and stops calling it when it keeps failing, so you fail fast instead of piling up slow requests. **Closed**: calls pass through while failures are counted. **Open**: after a threshold of failures, calls are rejected immediately (or served a fallback). **Half-open**: after a cool-down, a few trial calls test recovery and close or reopen the circuit.", "more": "- Prevents cascading failure: threads stuck on a dead dependency exhaust the caller.\n- Pair with timeouts, retries with backoff, bulkheads and fallbacks (cached data, default value).\n- Tune thresholds on error rate over a window, not single errors."},
    {"id": "sd-backpressure", "title": "Backpressure and load shedding", "q": ["what is backpressure", "how to handle overload in a system", "load shedding explained", "slow consumer fast producer", "bounded queue"], "tags": "backpressure load shedding bounded queue overload slow consumer rate limit throttle", "see": ["#/system-design/fundamentals/queues-pubsub"], "a": "Backpressure is how a slow consumer tells producers to slow down so queues don't grow without bound. Use **bounded queues**, make producers block or get rejected (HTTP 429/503) when full, and **shed load** (drop low-priority work) before the system collapses. An unbounded queue only hides overload and turns it into huge latency and memory blowup.", "more": "- Options when full: block the producer, drop newest or oldest, reject with an error, or spill to disk.\n- Pull-based consumers (Kafka) get natural backpressure because they read at their own pace.\n- Combine with autoscaling, priority queues and client retries with backoff."},
    {"id": "sd-exponential-backoff-jitter", "title": "Retries with exponential backoff and jitter", "q": ["exponential backoff with jitter python", "how to retry failed requests", "what is jitter in retries", "retry strategy for api calls", "backoff algorithm"], "tags": "retry exponential backoff jitter full jitter thundering herd timeout resilience python", "see": ["#/system-design/notification-system", "#/system-design/fundamentals/queues-pubsub"], "a": "Wait longer after each failure (`base * 2^attempt`, capped), and **add randomness (jitter)** so many clients that failed together don't retry in sync and hammer the recovering service. \"Full jitter\" sleeps a random time between 0 and the capped backoff. Retry only idempotent operations and only transient errors, with a max attempt count.", "code": {"py": "import random, time\n\ndef backoff_delay(attempt, base=0.1, cap=10.0):\n    return random.uniform(0, min(cap, base * 2 ** attempt))   # full jitter\n\ndef retry(fn, attempts=5, sleep=time.sleep):\n    for i in range(attempts):\n        try:\n            return fn()\n        except ConnectionError:\n            if i == attempts - 1:\n                raise\n            sleep(backoff_delay(i))\n\ncalls = []\ndef flaky():\n    calls.append(1)\n    if len(calls) < 3:\n        raise ConnectionError\n    return \"ok\"\n\nprint(retry(flaky, sleep=lambda s: None), len(calls))   # ok 3"}, "more": "- Cap the delay and total retry time; add a retry budget so retries don't multiply load across layers.\n- Respect `Retry-After` when the server sends it.\n- Without idempotency keys, retries of writes can duplicate effects.", "check": "assert all(0 <= backoff_delay(a) <= min(10.0, 0.1 * 2 ** a) for a in range(20) for _ in range(50))\nassert backoff_delay(50) <= 10.0\ncalls.clear()\nassert retry(flaky, sleep=lambda s: None) == \"ok\" and len(calls) == 3\ndef always():\n    raise ConnectionError\ntry:\n    retry(always, attempts=2, sleep=lambda s: None)\n    assert False\nexcept ConnectionError:\n    pass"},
    {"id": "sd-observability", "title": "Observability: metrics, logs and traces", "q": ["what is observability", "metrics vs logs vs traces", "three pillars of observability", "what to monitor in a system", "distributed tracing explained"], "tags": "observability metrics logs traces monitoring distributed tracing golden signals alerting prometheus", "see": ["#/system-design/fundamentals/observability"], "a": "**Metrics** are numbers over time (request rate, error rate, latency percentiles): cheap, good for dashboards and alerts. **Logs** are detailed event records: good for debugging a specific case. **Traces** follow one request across services with timing per hop, to find where latency or errors come from. Use metrics to detect, traces to locate, logs to explain.", "more": "- Golden signals: latency, traffic, errors, saturation.\n- Use percentiles (p50, p99), not averages; tail latency hides in the average.\n- Pass a request/trace ID through every service and log it.\n- Alert on symptoms users feel (SLO burn), not every cause."},
    {"id": "sd-slo-sla-sli", "title": "SLI vs SLO vs SLA", "q": ["sli slo sla difference", "what is an slo", "what is an error budget", "service level objective example", "sla vs slo"], "tags": "sli slo sla error budget availability latency target reliability", "see": ["#/system-design/fundamentals/observability"], "a": "An **SLI** is a measurement (e.g. fraction of requests under 300 ms, or successful). An **SLO** is the internal target for it (99.9% over 30 days). An **SLA** is the external contract with consequences (credits) if you miss, usually looser than the SLO. The **error budget** is `1 - SLO`: the failure you can spend on releases and risk.", "more": "- 99.9% over 30 days allows about 43 minutes of failure.\n- When the budget is spent, slow risky launches and fix reliability.\n- Pick a few SLIs that reflect user experience: availability, latency, correctness, freshness."},
    {"id": "sd-horizontal-vs-vertical", "title": "Horizontal vs vertical scaling", "q": ["horizontal vs vertical scaling", "scale up vs scale out", "how to scale a web application", "what is horizontal scaling", "scaling stateless servers"], "tags": "horizontal vertical scaling scale out scale up stateless load balancer autoscaling", "see": ["#/system-design/fundamentals/scaling"], "a": "**Vertical** scaling (scale up) makes one machine bigger: simplest, no code changes, but has a ceiling, costs rise steeply and it stays a single point of failure. **Horizontal** scaling (scale out) adds more machines behind a load balancer: nearly unlimited and fault tolerant, but needs stateless servers and a plan for data (replication, sharding).", "more": "- Start vertical (cheap and quick), go horizontal for the stateless web tier first.\n- Databases are the hard part: add read replicas, caching, then shard.\n- Keep sessions in a shared store or tokens so any server can handle any request."},
    {"id": "sd-estimate-qps-storage", "title": "Back-of-the-envelope: estimate QPS, storage and bandwidth", "q": ["how to estimate qps", "back of the envelope calculation system design", "how to estimate storage", "capacity estimation example", "how many servers do i need", "estimate bandwidth"], "tags": "back of the envelope estimation qps storage bandwidth capacity planning peak average seconds per day", "see": ["#/system-design/numbers", "#/system-design/url-shortener"], "a": "Work from users to requests per second: **QPS = requests per day / 86,400** (round to 10^5), then multiply by a peak factor (2 to 3). **Storage = records per day x bytes per record x retention days**, times replication. **Bandwidth = QPS x bytes per request.** Round aggressively and state your assumptions out loud.", "code": {"py": "SECONDS_PER_DAY = 86_400\n\ndef estimate(new_per_month, read_write_ratio, bytes_per_record, years, peak=3, replicas=3):\n    writes_per_day = new_per_month / 30\n    write_qps = writes_per_day / SECONDS_PER_DAY\n    read_qps = write_qps * read_write_ratio\n    total_records = new_per_month * 12 * years\n    storage_tb = total_records * bytes_per_record / 1e12\n    return {\n        \"write_qps\": round(write_qps),\n        \"read_qps\": round(read_qps),\n        \"peak_read_qps\": round(read_qps * peak),\n        \"storage_tb\": round(storage_tb, 1),\n        \"replicated_tb\": round(storage_tb * replicas, 1),\n        \"read_mb_per_s\": round(read_qps * bytes_per_record / 1e6, 1),\n    }\n\n# URL shortener: 100M new URLs/month, 100 reads per write, 500 bytes each, 5 years\nprint(estimate(100e6, 100, 500, 5))"}, "more": "- Worked: 100M/month is 3.3M/day, about 39 writes/s; 100x reads is about 4,000/s, peak ~12,000/s.\n- 6 billion records x 500 B = 3 TB (9 TB replicated).\n- One app server handles roughly 1K to 10K simple req/s, a Redis instance ~100K ops/s, so divide peak by that and add headroom.\n- Memory for a cache: store the hot 20% of a day's reads.", "check": "r = estimate(100e6, 100, 500, 5)\nassert r[\"write_qps\"] == 39 and r[\"read_qps\"] == 3858\nassert r[\"storage_tb\"] == 3.0 and r[\"replicated_tb\"] == 9.0\nassert r[\"peak_read_qps\"] == 11574"},
    {"id": "sd-availability-nines", "title": "Availability nines table", "q": ["availability nines", "what does 99.9 availability mean", "downtime per year for 99.99", "five nines downtime", "how much downtime is 99.9 percent"], "tags": "availability nines uptime downtime 99.9 99.99 99.999 sla per year per month", "see": ["#/system-design/numbers", "#/system-design/fundamentals/observability"], "a": "Downtime allowed per year: **99% = 3.65 days, 99.9% = 8.76 hours, 99.99% = 52.6 minutes, 99.999% = 5.26 minutes.** Per month that is about 7.2 hours, 43 minutes, 4.4 minutes and 26 seconds. Each extra nine is 10x less downtime and costs much more (redundancy, multi-region, automation).", "code": {"py": "def downtime_minutes(availability_pct, period_minutes=365 * 24 * 60):\n    return period_minutes * (1 - availability_pct / 100)\n\nfor a in (99, 99.9, 99.99, 99.999):\n    print(a, round(downtime_minutes(a), 1), \"min/year\")"}, "more": "- Serial dependencies multiply: two 99.9% services in a chain give about 99.8%.\n- Parallel redundancy improves it: two independent 99% replicas give 99.99%.\n- Plan for the weakest dependency, and measure real availability, not just uptime of processes.", "check": "assert round(downtime_minutes(99.9) / 60, 2) == 8.76\nassert round(downtime_minutes(99.99), 1) == 52.6\nassert round(downtime_minutes(99.999), 2) == 5.26"},
    {"id": "sd-latency-numbers", "title": "Latency numbers every engineer should know", "q": ["latency numbers every programmer should know", "ram vs ssd vs network latency", "how long does a disk seek take", "cross region latency", "order of magnitude latency"], "tags": "latency numbers ram ssd disk network round trip cache jeff dean orders of magnitude", "see": ["#/system-design/numbers"], "a": "Use ratios, not exact digits: **L1 cache ~1 ns, RAM ~100 ns, NVMe SSD random read ~20 to 100 µs, round trip inside a data center ~0.5 ms, spinning disk seek ~5 to 10 ms, cross-continent round trip ~100 to 150 ms.** Memory is ~1000x faster than SSD and a cross-region hop costs more than hundreds of thousands of RAM reads.", "more": "- Reading 1 MB sequentially: RAM ~50 µs, SSD ~0.3 to 1 ms, spinning disk ~5 to 20 ms.\n- Implication: avoid cross-region calls on the hot path, batch network calls, cache in memory, prefer sequential over random disk I/O.\n- Other handy numbers: 1 Gbps ~125 MB/s, a day ~86,400 s, 2^30 ~ 1 billion."},
    {"id": "sd-base62-code", "title": "Base62 encoding for short URLs", "q": ["base62 encoding python", "how to generate short url code from id", "encode integer to base62", "url shortener key generation", "convert id to short string"], "tags": "base62 encode decode short url code id counter bijection alphabet 62 characters", "see": ["#/system-design/url-shortener"], "a": "Take a unique integer ID and write it in base 62 (`0-9a-zA-Z`). Each character carries ~5.95 bits, and **7 characters give 62^7 = 3,521,614,606,208 (~3.5 trillion) codes**. Unlike hashing, encoding a unique ID can never collide.", "code": {"py": "ALPHABET = \"0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n\ndef encode(n):\n    if n == 0:\n        return ALPHABET[0]\n    out = []\n    while n:\n        n, r = divmod(n, 62)\n        out.append(ALPHABET[r])\n    return \"\".join(reversed(out))\n\ndef decode(s):\n    n = 0\n    for ch in s:\n        n = n * 62 + ALPHABET.index(ch)\n    return n\n\nprint(encode(125), decode(\"21\"))   # 21 125"}, "more": "- Sequential IDs give guessable, enumerable codes. Fix by scrambling the ID first (a bijective shuffle or XOR with a secret) or by allocating random IDs.\n- Hashing the long URL and truncating can collide, so you need a collision check.", "cx": "O(log n) in the ID", "check": "assert encode(0) == \"0\" and encode(61) == \"Z\" and encode(62) == \"10\"\nassert all(decode(encode(n)) == n for n in (0, 1, 61, 62, 10**12, 62**7 - 1))\nassert len(encode(62**7 - 1)) == 7 and 62**7 == 3521614606208"},
    {"id": "sd-unique-id-generation", "title": "How to generate unique IDs in a distributed system", "q": ["how to generate unique ids across servers", "uuid vs auto increment vs snowflake", "distributed id generator options", "ticket server", "sortable unique ids"], "tags": "unique id uuid auto increment snowflake ticket server ulid sortable distributed id generator", "see": ["#/system-design/url-shortener", "#/system-design/news-feed"], "a": "Options: **database auto-increment** (simple, single bottleneck, shard with step offsets), **UUID v4** (no coordination, 128 bits, random so poor index locality), **ticket server / ID blocks** (each app server leases a range from a central counter), and **Snowflake-style** 64-bit IDs (timestamp + machine ID + sequence): time-sortable, no coordination per ID. Choose Snowflake or ULID when you need sortable IDs.", "more": "- Random UUIDs scatter inserts across a B-tree index; time-ordered IDs append at the end.\n- Snowflake depends on clocks: handle clocks moving backwards.\n- Block allocation: lose unused IDs on crash, which is fine."},
    {"id": "sd-snowflake-code", "title": "Snowflake-style unique ID generator (code)", "q": ["implement snowflake id generator", "twitter snowflake explained", "64 bit unique id timestamp machine sequence", "how to build distributed id generator", "time ordered unique id python"], "tags": "snowflake id generator 64 bit timestamp machine id worker sequence twitter epoch k-sortable", "see": ["#/system-design/news-feed", "#/system-design/url-shortener"], "a": "A Snowflake ID packs **41 bits of millisecond timestamp (since a custom epoch), 10 bits of machine ID and 12 bits of per-millisecond sequence** into 64 bits. IDs are unique across machines without talking to each other, sort by time, and each machine can make 4,096 per millisecond. If the sequence overflows within a millisecond, wait for the next one.", "code": {"py": "import time\n\nclass Snowflake:\n    EPOCH = 1_700_000_000_000          # custom epoch in ms\n    def __init__(self, machine_id, clock=lambda: int(time.time() * 1000)):\n        assert 0 <= machine_id < 1024                   # 10 bits\n        self.machine, self.clock = machine_id, clock\n        self.last, self.seq = -1, 0\n\n    def next_id(self):\n        ts = self.clock()\n        if ts < self.last:\n            raise RuntimeError(\"clock moved backwards\")\n        if ts == self.last:\n            self.seq = (self.seq + 1) & 0xFFF           # 12 bits\n            if self.seq == 0:                           # exhausted: spin to next ms\n                while ts <= self.last:\n                    ts = self.clock()\n        else:\n            self.seq = 0\n        self.last = ts\n        return ((ts - self.EPOCH) << 22) | (self.machine << 12) | self.seq\n\ng = Snowflake(7)\na, b = g.next_id(), g.next_id()\nprint(a < b)   # True"}, "more": "- Machine IDs must be unique (assign via config service); never reuse one while old IDs are live.\n- 41 bits of ms is about 69 years from the epoch.\n- Not strictly ordered across machines (clock skew), only roughly time-sorted.", "cx": "O(1) per ID", "check": "t = [1_700_000_000_000 + 5]\ng = Snowflake(7, clock=lambda: t[0])\na, b = g.next_id(), g.next_id()\nassert a < b and (a >> 12) & 0x3FF == 7 and a >> 22 == 5\nassert b & 0xFFF == 1                                   # second ID in the same ms\nt[0] += 1\nc = g.next_id()\nassert c > b and c & 0xFFF == 0\nids = set()\ng2, g3 = Snowflake(1, clock=lambda: 1_700_000_000_100), Snowflake(2, clock=lambda: 1_700_000_000_100)\nids = {g2.next_id() for _ in range(100)} | {g3.next_id() for _ in range(100)}\nassert len(ids) == 200                                  # different machines never collide\nt[0] -= 5\ntry:\n    g.next_id(); assert False\nexcept RuntimeError:\n    pass"},
    {"id": "sd-interview-framework", "title": "How to approach a system design interview", "q": ["how to approach a system design interview", "system design interview steps", "how do i structure a system design answer", "what to say first in system design", "system design framework"], "tags": "system design interview framework steps requirements estimate api data model high level design deep dive bottlenecks", "see": ["#/system-design", "#/system-design/fundamentals/client-server-dns"], "a": "Go in this order: **1) clarify functional and non-functional requirements (scale, latency, availability, consistency); 2) estimate QPS, storage, bandwidth; 3) define the API; 4) sketch the data model and pick storage; 5) draw the high-level design; 6) deep dive on the hardest parts; 7) discuss bottlenecks, failures and trade-offs.** Say your assumptions and choices out loud.", "more": "- Spend about 5 minutes on requirements and 5 on estimates in a 45-minute round.\n- Name the read/write ratio early: it drives caching, sharding and storage choices.\n- For every component state why, and what would break first at 10x.\n- Ask the interviewer to pick which part to go deep on if unclear."},
    {"id": "sd-design-url-shortener", "title": "How do I design a URL shortener?", "q": ["how to design a url shortener", "design bit.ly", "design tinyurl", "url shortening service system design", "how does a url shortener work"], "tags": "url shortener tinyurl bitly short code redirect 301 302 base62 key value cache design", "see": ["#/system-design/url-shortener", "#/system-design/fundamentals/caching"], "a": "Two endpoints: `POST /v1/urls` creates a code, `GET /{code}` returns a **302** redirect (302 so clicks reach you; 301 gets cached by browsers). Store `code -> long URL` in a key-value store; generate codes by base62-encoding a unique ID (7 chars = 3.5 trillion). It's read-heavy (about 100:1), so put a cache in front of the store.", "more": "- **Estimate:** 100M new/month is about 40 writes/s and 4,000 reads/s; 500 B x 6B records is ~3 TB over 5 years.\n- **Data model:** `code (PK), long_url, owner, created_at, expires_at`.\n- **Design:** LB, stateless app servers, Redis cache (cache-aside), sharded KV/SQL store, ID allocator ranges per app server.\n- **Trade-offs:** hash+truncate collides; counters need coordination; hot viral links need cache and coalescing; custom aliases need a uniqueness check; rate limit creation.\n- See also: base62 code entry."},
    {"id": "sd-design-rate-limiter", "title": "How do I design a rate limiter?", "q": ["how to design a rate limiter", "design an api rate limiter", "distributed rate limiting redis", "system design rate limiter", "where to put the rate limiter"], "tags": "design rate limiter redis lua token bucket gateway distributed 429 fail open", "see": ["#/system-design/rate-limiter", "#/system-design/fundamentals/rate-limiting"], "a": "Run it as a filter in the API gateway: per client key (API key, user, IP) and rule, keep a **token bucket in Redis** updated by an atomic Lua script, reject with **429 + Retry-After** when empty. Rules live in a config store and reload without deploys. Decide the failure mode: normally **fail open**, but fail closed for login and abuse-sensitive endpoints.", "more": "- **Estimate:** a few hundred thousand checks/s; ~100 B per key, so millions of active keys fit in a few GB; shard Redis by client key.\n- **Algorithm:** token bucket allows bursts; sliding window counter is cheaper and smoother than fixed windows.\n- **Trade-offs:** exactness vs latency (local counters synced periodically are approximate); NAT makes many users share an IP; multi-region limits need a split budget.\n- **Bottlenecks:** hot keys, the extra Redis hop (~1 ms), clock handling (use Redis time)."},
    {"id": "sd-design-typeahead", "title": "How do I design search autocomplete (typeahead)?", "q": ["how to design autocomplete", "design typeahead search suggestions", "trie for autocomplete", "search suggestion system design", "top k suggestions for a prefix"], "tags": "typeahead autocomplete trie prefix top k suggestions search queries aggregation cache", "see": ["#/system-design/typeahead", "#/system-design/fundamentals/search-indexes"], "a": "Precompute, for every prefix, the **top-k (e.g. 5 to 10) most popular completions** in a trie or a prefix-to-list key-value table; the query path is then one lookup, served from cache and the CDN. Build the data offline from aggregated search logs on a schedule, and overlay a small fast-moving trending layer for fresh queries.", "more": "- **Requirements:** very low latency (under ~100 ms), high availability, suggestions can be slightly stale.\n- **API:** `GET /suggest?q=pre`; clients debounce keystrokes and cache.\n- **Pipeline:** log queries, aggregate counts (batch or stream), build a new snapshot, swap atomically.\n- **Trade-offs:** storing top-k at each node uses memory but avoids subtree scans; shard by prefix with care for skew (\"s\" is huge); filter bad queries."},
    {"id": "sd-design-web-crawler", "title": "How do I design a web crawler?", "q": ["how to design a web crawler", "design google crawler", "crawler url frontier", "politeness in web crawling", "avoid crawling duplicate urls"], "tags": "web crawler url frontier politeness robots txt bloom filter dedupe dns fingerprint distributed", "see": ["#/system-design/web-crawler", "#/system-design/fundamentals/blob-storage"], "a": "Loop: take a URL from the **frontier** (priority plus per-host politeness queues), resolve DNS, honour robots.txt, fetch, parse, store the content in blob storage, extract links, normalize them, drop ones already seen (a **Bloom filter** plus a durable URL table) and add new ones. Partition the crawl by host so one worker owns a site's politeness.", "more": "- **Estimate:** pages/s x average page size gives bandwidth; billions of URLs need a sharded seen-set.\n- **Key points:** per-host rate limits, DNS caching, content fingerprints to catch duplicates, crawl-trap limits (depth, URL patterns), recrawl scheduling by change rate.\n- **Failures:** workers lease URLs and re-queue on timeout; back off on 429/5xx."},
    {"id": "sd-design-news-feed", "title": "How do I design a news feed?", "q": ["how to design a news feed", "design twitter timeline", "fan out on write vs fan out on read", "design facebook feed", "celebrity problem feed"], "tags": "news feed timeline fan out write read celebrity hybrid followers redis ranking social", "see": ["#/system-design/news-feed", "#/system-design/fundamentals/caching"], "a": "Use a **hybrid fan-out**: when a normal user posts, push the post ID into each follower's precomputed timeline (a Redis list or sorted set), so reads are one cache lookup. For celebrities with millions of followers, skip the push and merge their recent posts into the timeline **at read time**. Then hydrate the post IDs, rank, and return a page with a cursor.", "more": "- **Data:** posts table (sharded by post ID), follow graph, per-user timeline of IDs, post IDs time-sortable (Snowflake).\n- **Trade-offs:** write fan-out costs storage and write amplification; read fan-out costs latency; cap timeline length (a few hundred IDs).\n- **Details:** cursor pagination, handle deletes/unfollows lazily, rebuild timelines after a cache loss."},
    {"id": "sd-design-chat", "title": "How do I design a chat system (WhatsApp, Slack)?", "q": ["how to design a chat application", "design whatsapp", "design messaging system", "how do chat messages get delivered", "websocket chat architecture"], "tags": "chat messaging whatsapp slack websocket gateway sequence number offline sync group chat presence", "see": ["#/system-design/chat", "#/system-design/fundamentals/queues-pubsub"], "a": "Clients keep a **WebSocket to a chat gateway**. A send goes to a chat service that assigns a per-conversation **sequence number**, stores the message durably (wide-column store, partitioned by conversation), then looks up the recipient's gateway in a session store and pushes it; if offline, it sends a push notification and the client syncs missing messages by sequence number on reconnect.", "more": "- **Delivery:** at-least-once with client acks and dedupe by message ID; ordering via per-conversation sequence.\n- **Groups:** store once, fan out to members' devices; huge groups need batching.\n- **Scale:** millions of connections need many gateway servers; plan for reconnect storms.\n- **Extras:** read receipts, presence (heartbeat with TTL), media in blob storage, end-to-end encryption."},
    {"id": "sd-design-notification-system", "title": "How do I design a notification system?", "q": ["how to design a notification system", "design push notification service", "email sms push notification architecture", "notification service retries and dedupe", "system design notifications"], "tags": "notification system push email sms queue priority retry dedupe preferences provider template", "see": ["#/system-design/notification-system", "#/system-design/fundamentals/queues-pubsub"], "a": "Callers submit an event to an API that validates it, **dedupes by idempotency key**, stores it, and enqueues it. Workers apply user **preferences and rate limits**, render a template, and send through per-channel queues (push, email, SMS) with separate worker pools so one slow provider can't block others. Retry with backoff, trip circuit breakers on provider failure and record delivery status.", "more": "- **Priority:** OTP and security alerts use a high-priority queue; marketing batches use a low one.\n- **Delivery:** at-least-once plus dedupe; providers can send duplicates or lose messages.\n- **Bottlenecks:** provider throughput limits, bursts and head-of-line blocking, stale preferences, SMS cost.\n- **Data:** notification log, preferences, templates, dedupe keys in Redis."},
    {"id": "sd-design-video-streaming", "title": "How do I design a video streaming service (YouTube, Netflix)?", "q": ["how to design youtube", "design netflix video streaming", "adaptive bitrate streaming explained", "video upload and transcoding pipeline", "hls dash cdn"], "tags": "video streaming youtube netflix transcoding adaptive bitrate hls dash cdn object storage chunks", "see": ["#/system-design/video-streaming", "#/system-design/fundamentals/cdn"], "a": "Upload the original in chunks to **object storage**, then a queue-driven **transcoding pipeline** splits it into segments and encodes multiple resolutions/bitrates. Segments plus a manifest (HLS or DASH) are published to storage and served through a **CDN**; the player picks quality per segment based on bandwidth (**adaptive bitrate**). Metadata lives in a database, search in an inverted index, and views are counted via an event log.", "more": "- **Estimate:** bitrate x duration / 8 gives size (1 minute at 5 Mbps is ~37 MB); egress cost dominates, so CDN hit ratio matters most.\n- **Trade-offs:** more renditions use more storage; tier cold videos to cheaper storage; transcoding is bursty so autoscale workers.\n- **Hot videos:** pre-warm CDN and use origin shield."},
    {"id": "sd-design-file-sync", "title": "How do I design Dropbox / file sync?", "q": ["how to design dropbox", "design google drive file sync", "file chunking and deduplication", "sync conflict resolution", "delta sync design"], "tags": "dropbox file sync google drive chunking dedupe delta sync conflict block storage metadata journal", "see": ["#/system-design/file-sync", "#/system-design/fundamentals/blob-storage"], "a": "Split files into chunks (a few MB), hash each chunk, and upload only chunks the server doesn't already have (**dedupe and delta sync**) to block storage; a **metadata database** records the file as an ordered list of chunk hashes and versions. Every commit appends to a per-namespace **journal**; a notification service pings other devices, which read the journal from their cursor and download missing chunks.", "more": "- **Conflicts:** compare base versions; first commit wins, the other becomes a \"conflicted copy\".\n- **Scale:** metadata is sharded by namespace/user; chunks live in replicated object storage; garbage collect unreferenced chunks.\n- **Edge cases:** huge initial syncs, offline edits, permissions on shared folders, reconnect storms."},
    {"id": "sd-design-ticket-booking", "title": "How do I design a ticket booking system (Ticketmaster)?", "q": ["how to design ticketmaster", "prevent double booking seats", "design movie ticket booking", "flash sale ticket system design", "seat reservation hold timeout"], "tags": "ticket booking seat reservation double booking hold expiry waiting room flash sale inventory", "see": ["#/system-design/ticket-booking", "#/system-design/fundamentals/consistency-models"], "a": "Treat each seat as a row with state `available -> held -> sold`. **Prevent double booking with an atomic conditional update** (`UPDATE seats SET status='held', hold_until=... WHERE id=? AND status='available'`; one winner). A hold lasts a few minutes and a sweeper (or expiry check) releases it; payment confirms it to `sold` idempotently. For on-sale spikes add a **waiting room** that admits users at a controlled rate.", "more": "- **Consistency:** seat state needs strong consistency (CP); browse and search can be eventually consistent and cached.\n- **Hot shard:** one popular event concentrates load, so isolate and rate limit it.\n- **Payments:** idempotency keys; if payment completes after the hold expires, refund or re-check.\n- **Fairness:** anti-bot measures, per-user purchase limits."},
    {"id": "sd-design-ride-matching", "title": "How do I design ride matching (Uber)?", "q": ["how to design uber", "ride matching system design", "find nearby drivers geohash", "geospatial index quadtree", "driver location updates"], "tags": "ride matching uber lyft geohash quadtree s2 nearby drivers location dispatch eta geospatial", "see": ["#/system-design/ride-matching", "#/system-design/fundamentals/consistent-hashing"], "a": "Drivers send location pings every few seconds into an **in-memory geospatial index** (geohash or S2/quadtree cells) so \"drivers near this point\" is a lookup of the rider's cell and its neighbours. Dispatch shortlists nearby available drivers, ranks by ETA, then **atomically claims one** (state machine `available -> offered -> assigned`) so no driver is assigned twice; if declined, offer the next.", "more": "- **Estimate:** a million drivers pinging every 4 s is about 250K writes/s; location data is ephemeral, keep it in memory, log to a stream for history.\n- **Trade-offs:** cell size vs candidates; sequential vs parallel offers (latency vs wasted offers); hot cells downtown.\n- **Rider updates:** push (WebSocket) over polling. Trip state in a transactional store."},
    {"id": "sd-design-distributed-kv-store", "title": "How do I design a distributed key-value store?", "q": ["how to design a key value store", "design dynamo", "design distributed database", "distributed kv store replication consistent hashing", "design cassandra"], "tags": "distributed key value store dynamo cassandra consistent hashing replication quorum gossip lsm vector clock hinted handoff", "see": ["#/system-design/distributed-kv-store", "#/system-design/fundamentals/consistent-hashing"], "a": "Partition keys with **consistent hashing and virtual nodes**; replicate each key to N nodes; read and write with **quorums (R + W > N)**. Each node stores data in an **LSM tree** (WAL, memtable, SSTables). Any node can coordinate a request. Handle failures with **hinted handoff, read repair and Merkle-tree anti-entropy**, detect membership with **gossip**, and resolve conflicts with vector clocks or last-write-wins.", "more": "- **API:** `get(key)`, `put(key, value)`, `delete(key)` (tombstone).\n- **Trade-offs:** W=1 is fast but may lose data; strong consistency costs availability (CAP/PACELC).\n- **Bottlenecks:** hot keys, compaction I/O, slowest-replica tail latency, repair streaming load."},
    {"id": "sd-design-payment-system", "title": "How do I design a payment system?", "q": ["how to design a payment system", "design stripe", "how to avoid double charging", "double entry ledger", "payment reconciliation design"], "tags": "payment system stripe idempotency ledger double entry psp webhook reconciliation state machine", "see": ["#/system-design/payment-system", "#/system-design/fundamentals/consistency-models"], "a": "Correctness over speed. Every request carries an **idempotency key**, claimed atomically before calling the payment provider (PSP). Model each payment as a **state machine** (created, processing, succeeded, failed) in an ACID database, record money movement in an **append-only double-entry ledger**, and treat a PSP timeout as \"unknown\": resolve it by querying the PSP or waiting for its webhook. Reconcile daily against PSP reports.", "more": "- **Consistency:** strong inside the ledger/payment DB; downstream analytics can be eventual.\n- **Webhooks:** verify signatures, process idempotently (they duplicate and arrive out of order).\n- **Security:** tokenize card data to shrink PCI scope.\n- **Hot rows:** a busy merchant's balance; use per-entry rows and aggregate."},
    {"id": "sd-design-id-generator", "title": "How do I design a unique ID generator service?", "q": ["design a unique id generator", "system design distributed id generation", "design twitter snowflake", "globally unique sortable ids service", "id generator requirements"], "tags": "design id generator snowflake unique sortable 64 bit clock skew machine id ticket server", "see": ["#/system-design/news-feed", "#/system-design/url-shortener"], "a": "Requirements: IDs unique across servers, roughly time-sortable, 64-bit, thousands per second per node, no per-ID coordination. Use **Snowflake**: 41-bit ms timestamp, 10-bit machine ID, 12-bit sequence, generated locally in each app server or a small stateless service. Machine IDs are assigned once from a coordination service (etcd/ZooKeeper).", "more": "- **Capacity:** 4,096 IDs/ms per machine, 1,024 machines, ~69 years.\n- **Risks:** clock going backwards (refuse or wait), machine ID reuse, clock skew breaking strict order.\n- **Alternatives:** UUID (no order), DB ticket server or ID-range leasing (central dependency), ULID.\n- See the Snowflake code entry for an implementation."},
    {"id": "sd-design-distributed-cache", "title": "How do I design a distributed cache (Redis/Memcached cluster)?", "q": ["how to design a distributed cache", "design redis cluster", "distributed cache architecture", "cache cluster sharding replication", "design memcached"], "tags": "distributed cache redis memcached cluster consistent hashing replication eviction lru ttl hot key", "see": ["#/system-design/fundamentals/caching", "#/system-design/fundamentals/consistent-hashing"], "a": "Shard keys across cache nodes with **consistent hashing** (clients or a proxy route by key), keep each node in memory with an **LRU/LFU eviction** policy and per-key **TTL**, and add a **replica per shard** for failover. The app uses **cache-aside**; clients tolerate misses. Protect the database from stampedes with request coalescing, TTL jitter and negative caching.", "more": "- **Estimate:** sizes = hot dataset x bytes; one node ~100K ops/s.\n- **Trade-offs:** replication gives availability but async replicas can lose recent writes; no strong consistency with the DB.\n- **Hot keys:** local in-process cache, key replication or salting.\n- **Resizing:** consistent hashing keeps most keys in place; warm new nodes."},
    {"id": "sd-design-pastebin", "title": "How do I design Pastebin?", "q": ["how to design pastebin", "design a text sharing service", "pastebin system design", "store and share text snippets", "design gist"], "tags": "pastebin text snippet share object storage expiry key generation read heavy metadata", "see": ["#/system-design/url-shortener", "#/system-design/fundamentals/blob-storage"], "a": "Like a URL shortener, but the value is a blob. `POST /pastes` stores the text in **object storage** and metadata (`id, owner, created_at, expires_at, visibility, size`) in a database; the ID is a short random or base62 key from a key service. `GET /{id}` reads metadata, then the text from cache, CDN or object storage. Reads far outnumber writes, so cache and CDN the content.", "more": "- **Estimate:** 1M pastes/day x 10 KB is 10 GB/day, ~3.6 TB/year; store large text in blob storage, tiny text inline.\n- **Expiry:** TTL field plus a background cleanup job; lazy check on read.\n- **Trade-offs:** unguessable IDs for private pastes; size limits and rate limits against abuse; compress text."},
    {"id": "sd-design-leaderboard", "title": "How do I design a real-time leaderboard?", "q": ["how to design a leaderboard", "redis sorted set leaderboard", "top k players ranking system design", "game leaderboard rank of a user", "real time ranking"], "tags": "leaderboard ranking redis sorted set zset top k rank score game sharding", "see": ["#/system-design/fundamentals/databases", "#/system-design/fundamentals/replication-sharding"], "a": "Use a **Redis sorted set**: `ZADD board score player` to update, `ZREVRANGE board 0 9` for the top 10, and `ZREVRANK board player` for a player's rank, all O(log n). One node handles millions of players. For more, shard by score range (or per region/season) and merge top-k from shards; persist scores in a database as the source of truth.", "code": {"py": "import bisect\n\nclass Leaderboard:\n    def __init__(self):\n        self.score, self.sorted = {}, []        # sorted holds (score, player) ascending\n\n    def update(self, player, score):\n        if player in self.score:\n            self.sorted.remove((self.score[player], player))   # O(n) here; a skip list/tree is O(log n)\n        self.score[player] = score\n        bisect.insort(self.sorted, (score, player))\n\n    def top(self, k):\n        return [(p, s) for s, p in reversed(self.sorted[-k:])]\n\n    def rank(self, player):                     # 1 = best\n        return len(self.sorted) - bisect.bisect_left(self.sorted, (self.score[player], player))\n\nlb = Leaderboard()\nfor p, s in [(\"a\", 50), (\"b\", 90), (\"c\", 70)]:\n    lb.update(p, s)\nprint(lb.top(2), lb.rank(\"c\"))   # [('b', 90), ('c', 70)] 2"}, "more": "- **Estimate:** 10M players x ~50 B is about 500 MB, which fits in memory.\n- **Trade-offs:** exact global rank for everyone is costly at huge scale; show top-N exactly and approximate rank (percentile buckets) for the rest.\n- Time windows: one sorted set per day/week, expire old ones.\n- Hot writes: batch score updates through a queue.", "check": "lb = Leaderboard()\nfor p, s in [(\"a\", 50), (\"b\", 90), (\"c\", 70)]:\n    lb.update(p, s)\nassert lb.top(2) == [(\"b\", 90), (\"c\", 70)] and lb.rank(\"c\") == 2 and lb.rank(\"a\") == 3\nlb.update(\"a\", 100)\nassert lb.top(1) == [(\"a\", 100)] and lb.rank(\"b\") == 2"},
    {"id": "sd-design-search-engine", "title": "How do I design a search engine?", "q": ["how to design a search engine", "design google search", "inverted index explained", "how does full text search work", "design elasticsearch"], "tags": "search engine inverted index tokenization ranking tf idf crawler sharding scatter gather elasticsearch", "see": ["#/system-design/fundamentals/search-indexes", "#/system-design/web-crawler"], "a": "Pipeline: **crawl** pages, **parse and tokenize** (lowercase, stem, drop stopwords), build an **inverted index** (term to sorted list of document IDs with positions/frequencies), and answer a query by intersecting those posting lists and **ranking** (TF-IDF/BM25 plus signals like link authority and freshness). Shard the index by document, query all shards in parallel (scatter-gather) and merge their top results.", "more": "- **Serving:** cache popular queries, replicate shards for throughput and availability, put top-k per shard in memory.\n- **Updates:** build new index segments continuously and merge them in the background; big rebuilds in batch.\n- **Trade-offs:** document-sharded index has simple writes but fans out every query; term-sharded needs cross-node joins."}
  );
})();
